@Composable fun SettingsScreen(m:DressModel,n:Navigator){val uri=LocalUriHandler.current;Page{Heading("Personal by nature","Make it yours.");SectionLabel("The personal style studio");FormCard{FormRow(if(m.studioAvailable)"Dress Pro · Unlocked"else"Discover Dress Pro",icon=Icons.Outlined.AutoAwesome){n.open("pro")};Caption("Weekly outfits, your wardrobe, travel capsules and the full editorial collection. A one-time purchase; no subscription.");TextButton({m.pro.refresh(true)},enabled=!m.pro.purchasing){Text("Restore Pro Purchase",color=Ink)};m.pro.message?.let{Caption(it)}};SectionLabel("Your style");FormCard{Choice("Daily occasion",Occasion.entries.map{it.label},m.p.style.label){s->m.edit{it.copy(style=Occasion.valueOf(s))}};Text("Temperature comfort",color=Ink);Slider(m.p.comfort.toFloat(),{v->m.edit{it.copy(comfort=v.toDouble())}},valueRange=-5f..5f,steps=9,colors=SliderDefaults.colors(thumbColor=Olive,activeTrackColor=Olive));Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Caption("I run warm");Caption("I feel cold")};Caption(if(m.p.comfort==0.0)"Standard layering suggestions"else if(m.p.comfort>0)"Prefer warmer layers"else"Prefer lighter layers",color=Olive)};SectionLabel("Your weather");FormCard{SwitchRow("Fahrenheit (°F)",m.p.fahrenheit){value->m.edit{it.copy(fahrenheit=value)}};FormRow("Saved places",icon=Icons.Outlined.Place){n.open("locations")};FormRow(if(m.locating)"Finding your location…"else"Use current location",icon=Icons.Outlined.NearMe){n.location()};m.error?.let{Caption(it,color=Color(0xFFAD3838))}};SectionLabel("A better morning");FormCard{Choice("Remind me at",(5..12).map{"$it:00"},"${m.p.reminderHour}:00"){hour->m.edit{it.copy(reminderHour=hour.substringBefore(':').toInt())}};TextButton({n.enableReminder()}){Text("Enable daily reminder",color=Ink)};TextButton({m.reminder(false)}){Text("Turn off reminder",color=Ink)};m.message?.let{Caption(it)}};Caption("A local reminder invites you to open the app. It doesn’t send forecasts that may have gone stale overnight.");SectionLabel("Private, uncomplicated");FormCard{FormRow("Privacy & data"){n.open("privacy")};FormRow("Weather & credits"){n.open("credits")};FormRow("Add a widget"){n.open("widgets")};FormRow("Support & feedback"){uri.openUri("https://github.com/oanaunc/dress_by_the_weather/issues")}};Column(verticalArrangement=Arrangement.spacedBy(8.dp)){EditorialText("Dress by the Weather",25);Caption("Your forecast. Your outfit.");Caption("Version 1.0 · No account. No ads.")}}}
@Composable fun PrivacyScreen(m:DressModel){var deletion by remember{mutableStateOf(false)};val uri=LocalUriHandler.current;Page{Heading("Privacy · November 26, 2026","Your style stays\nyours.");PrivacyParagraph("No account, no tracking","We don’t run an account service, advertising, analytics or tracking SDKs. Your style preferences, comfort feedback, saved looks, cities and trips are stored on this device. Android backup is disabled for this app.");PrivacyParagraph("Optional location","If you allow location access, we use an approximate device location while the app is open. You can choose a city instead and change permission in Android Settings. Coordinates are truncated to four decimal places before weather requests.");PrivacyParagraph("Weather requests","Forecasts are requested directly from MET Norway. MET receives the requested coordinates and your IP address in order to deliver its service. This applies to searched places as well as current location. Weather responses are cached on this device to reduce requests.");TextButton({uri.openUri("https://www.met.no/en/About-us/Privacy")}){Text("MET Norway privacy policy")};PrivacyParagraph("Searching for places","Search uses the device’s Android geocoder, whose provider may receive your query and IP address. When unavailable, Photon (komoot) is used with OpenStreetMap data. Photon receives the typed search and your IP address; device location is not sent with a city search. Time zones are looked up offline. You can also enter latitude, longitude.");PrivacyParagraph("Reminders & removal","Reminders are scheduled locally, with your permission. Deleting a look or trip removes it from the app. Uninstalling removes local app data. Widgets use a small locally shared snapshot of the last forecast you opened.");PrivacyParagraph("Your Pro wardrobe","Wardrobe pieces, optional photos, weekly plans, saved inspiration and travel capsules stay in this app on your device. The photo picker shares only images you select. Photos are not uploaded or analyzed by a cloud AI service.");PrivacyParagraph("Pro purchases","Google Play processes the optional one-time Pro purchase. The app verifies the signed purchase and restores your entitlement from your Google Account. We do not receive payment card information or run a purchase-verification server. The signed purchase proof is kept in private app storage for offline verification and refreshed when Google Play is available.");TextButton({uri.openUri("https://www.oanarinaldi.com/dressbytheweatherandroidprivacy.html")}){Text("Published privacy policy")};TextButton({deletion=true}){Text("Delete saved Pro Studio data",color=Color(0xFFAD3838))};m.message?.let{Caption(it)};TextButton({uri.openUri("https://github.com/oanaunc/dress_by_the_weather/issues")}){Text("Contact via GitHub issues")}}
    if(deletion)AlertDialog(onDismissRequest={deletion=false},title={Text("Delete Studio data?")},text={Text("Delete wardrobe pieces and photos, weekly plans, capsules and saved editorial inspiration from this device?")},confirmButton={TextButton({m.clearStudio();deletion=false}){Text("Delete Studio data")}},dismissButton={TextButton({deletion=false}){Text("Cancel")}})
}
@Composable fun PrivacyParagraph(title:String,body:String){Column(verticalArrangement=Arrangement.spacedBy(10.dp)){EditorialText(title,26);Body(body)}}
@Composable fun CreditsScreen(){val uri=LocalUriHandler.current;Page{Heading("Considered sources","Weather & credits");SectionLabel("Free global forecasts");FormCard{FormRow("MET Norway Locationforecast"){uri.openUri("https://api.met.no/weatherapi/locationforecast/2.0/documentation")};FormRow("Data licence: CC BY 4.0"){uri.openUri("https://creativecommons.org/licenses/by/4.0/")};FormRow("Provider terms of service"){uri.openUri("https://api.met.no/doc/TermsOfService")};Caption("Weather data are provided by MET Norway. Daily ranges are derived from available forecast samples. Outfit advice is created by this app; MET Norway does not endorse it.")};SectionLabel("Feels-like estimates");FormCard{Caption("Estimated from temperature, wind and humidity. Wind chill is used at ≤10°C with wind above 4.8 km/h. Other conditions use the Bureau of Meteorology shade apparent-temperature formula. These values are estimates, not MET Norway observations.");FormRow("Apparent temperature formula"){uri.openUri("https://www.bom.gov.au/info/thermal_stress/")}};SectionLabel("Photography");FormCard{Caption("Fashion photography created in Midjourney with fictional adult models. Backgrounds are editorial scenes, not views of the selected location.")};SectionLabel("Place search & time zones");FormCard{FormRow("Photon · komoot"){uri.openUri("https://photon.komoot.io")};FormRow("OpenStreetMap · ODbL attribution"){uri.openUri("https://www.openstreetmap.org/copyright")};FormRow("Offline tz-lookup · CC0"){uri.openUri("https://github.com/photostructure/tz-lookup")};Caption("Place search uses the Android geocoder, with Photon as a fallback. Public geocoding has no guaranteed availability. Time-zone lookup is approximate near some boundaries; local legal time should be checked for travel.")};SectionLabel("Typography & open source");FormCard{Caption("Source Serif 4 © Adobe, and Inter © Rasmus Andersson: SIL Open Font License 1.1. Font license files are bundled in this app. AndroidX, Kotlin, Coil and Google Play Billing use their respective open-source or SDK licenses.");FormRow("Source Serif license"){uri.openUri("https://github.com/adobe-fonts/source-serif/blob/release/LICENSE.md")};FormRow("Inter license"){uri.openUri("https://github.com/rsms/inter/blob/master/LICENSE.txt")}}}}
@Composable fun WidgetHelpScreen(){val context=LocalContext.current;Page{Heading("At a glance","Your morning,\none step closer.");listOf("Touch and hold an empty part of your Home Screen.","Tap Widgets.","Search for Dress by the Weather and choose the weather-and-outfit widget.","Open the app to refresh the forecast. The widget shows its last update and never claims stale weather is live.").forEachIndexed{i,text->Row(horizontalArrangement=Arrangement.spacedBy(18.dp)){EditorialText("${i+1}",30,color=Olive);Text(text,color=Ink)}};Caption("Widget availability and Lock Screen support depend on your device and launcher.");Action("Add Home Screen widget",Modifier.fillMaxWidth(),primary=true){val manager=android.appwidget.AppWidgetManager.getInstance(context);if(android.os.Build.VERSION.SDK_INT>=26&&manager.isRequestPinAppWidgetSupported)manager.requestPinAppWidget(android.content.ComponentName(context,DressWidget::class.java),null,null)}}}
